script.setup:
// @mapbox/tiny-sdf renders each glyph to a signed distance field. The glyph fields are merged into one
// field for the whole word (max of distances = union of shapes), uploaded as a single-channel
// texture, and the shader turns distance into fill, outlines, glow and a shadow that follows the pointer.
const mod = await ctx.utils.import("https://esm.sh/@mapbox/tiny-sdf@2.2.0");
const TinySDF = mod.default ?? mod;
const FONT = 128, BUF = 64, RADIUS = 96;
const sdf = new TinySDF({ fontSize: FONT, buffer: BUF, radius: RADIUS, cutoff: 0.25, fontFamily: "Helvetica Neue, Arial, sans-serif", fontWeight: "800" });
const WORDS = ["SILJANGNIM", "Tiny SDF", "glyph", "실장님"];
const gl = ctx.gl, tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
// Lay out a word: each glyph's field goes in at its pen position; overlaps keep the larger value.
const layout = (text) => {
  const glyphs = [...text].map((ch) => sdf.draw(ch));
  const width = Math.ceil(glyphs.reduce((a, g) => a + g.glyphAdvance, 0)) + BUF * 4;
  const height = Math.ceil(FONT * 1.3) + BUF * 2, base = Math.round(FONT * 0.98) + BUF;
  const field = new Uint8Array(width * height);
  let pen = BUF * 2;
  for (const g of glyphs) {
    const x0 = Math.round(pen + g.glyphLeft - BUF), y0 = base - g.glyphTop - BUF;
    for (let y = 0; y < g.height; y++) for (let x = 0; x < g.width; x++) {
      const X = x0 + x, Y = y0 + y;
      if (X < 0 || Y < 0 || X >= width || Y >= height) continue;
      const i = Y * width + X, v = g.data[y * g.width + x];
      if (v > field[i]) field[i] = v;
    }
    pen += g.glyphAdvance;
  }
  return { field, width, height };
};
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_sdf; uniform vec2 u_fit; uniform vec2 u_texSize; uniform vec2 u_resolution; uniform vec4 u_mouse; uniform float u_time;
uniform float u_radius; uniform float u_reach; uniform float u_weight; uniform float u_outline; uniform float u_glow; uniform float u_wave;
uniform vec3 u_fill; uniform vec3 u_line; uniform vec3 u_glowColor;
// signed distance in field pixels, positive inside
float dist(vec2 q) { return (texture(u_sdf, vec2(q.x, 1.0 - q.y)).r - 0.75) * u_radius; }
void main() {
  vec2 q = (v_uv - 0.5) / u_fit + 0.5;
  q.y += u_wave * 0.04 * sin(q.x * 12.0 - u_time * 2.0);
  float px = 1.0 / (u_fit.x * u_resolution.x / u_texSize.x); // field pixels per screen pixel
  float d = dist(q) + u_weight;
  vec3 bg = mix(vec3(0.05, 0.04, 0.09), vec3(0.11, 0.07, 0.16), v_uv.y);
  vec3 c = bg;
  // glow: falls off with distance outside the glyphs, pulsing
  float pulse = 0.75 + 0.25 * sin(u_time * 2.5);
  // glyph images only reach BUF pixels past the ink, so fade out before that
  float reach = u_reach;
  c += u_glowColor * u_glow * pulse * 1.6 * pow(clamp(1.0 + d / reach, 0.0, 1.0), 1.6) * step(d, 0.0);
  // shadow, offset away from the pointer
  vec2 m = u_mouse.xy / u_resolution - 0.5;
  vec2 off = -normalize(m + vec2(1e-4, -1e-4)) * min(length(m), 0.5) * 0.05;
  float ds = dist(q - off / u_fit) + u_weight;
  c = mix(c, vec3(0.0), smoothstep(-6.0, 4.0, ds) * 0.55 * step(d, 0.0));
  // outline band outside the fill
  float ol = smoothstep(-u_outline - px, -u_outline + px, d);
  c = mix(c, u_line, ol);
  // fill with a vertical gradient and a gap before the outline
  float fill = smoothstep(-px, px, d);
  float gap = smoothstep(-px, px, d + min(u_outline * 0.4, 4.0)) - fill;
  vec3 fc = mix(u_fill, u_fill * 0.55 + 0.45, smoothstep(0.2, 0.9, q.y));
  c = mix(c, bg, gap * step(0.5, u_outline));
  c = mix(c, fc, fill);
  outColor = vec4(c, 1.0);
}`;
Object.assign(ctx.state, { layout, WORDS, tex, word: -1, size: [1, 1], RADIUS, BUF, p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const word = Math.max(0, Math.min(s.WORDS.length - 1, u.u_word | 0));
if (word !== s.word) {
  s.word = word;
  const { field, width, height } = s.layout(s.WORDS[word]);
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, width, height, 0, gl.RED, gl.UNSIGNED_BYTE, field);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 4);
  s.size = [width, height];
  ctx.publish("field size", `${width}×${height}`);
}
const img = s.size[0] / s.size[1], view = w / h;
const fit = img > view ? [0.96, 0.96 * view / img] : [0.96 * img / view, 0.96];
gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_sdf", s.tex, 0);
ctx.utils.drawFullscreen(s.p, { u_fit: fit, u_texSize: s.size, u_radius: s.RADIUS, u_reach: s.BUF - 6 });
